if(a.type==='tab'){s.tab=a.value;return s;}
if(a.type==='view'){s.view=a.value;if(PANELS.find(p=>p[0]===s.panel)?.[3]!==a.value)s.panel=PANELS.find(p=>p[3]===a.value)?.[0]||s.panel;return s;}
if(a.type==='filter'){s.filter=a.value;return s;}
if(a.type==='panel'){s.panel=a.value;const p=PANELS.find(p=>p[0]===a.value);s.view=p[3];return s;}
if(a.type==='create'){if(!can(s,'reception'))return deny('Reception creates requests.');const duplicate=s.orders.find(o=>o.vin===(a.vin||'DEMO-VEHICLE-001')&&o.requestedAt===(a.appointment||'2026-10-14T10:00')&&!['cancelled','no-show','completed'].includes(o.status));if(duplicate){s.selected=duplicate.id;s.page='inspection';s.tab='intake';return ok('Existing request '+duplicate.id+' reopened. Duplicate vehicle/time request was not created.');}const n=newOrder(s,a);s.orders.push(n);s.selected=n.id;s.page='inspection';s.tab='intake';return ok('Request created. The appointment still needs manual confirmation.');}
if(a.type==='viewer'){s.viewer=a.value;return s;}
if(a.type==='template-clone'){if(!can(s,'manager'))return deny('Checklist manager access required.');s.templateDraft=copy(s.template);s.templateDraft.version++;return ok('Draft copied. Existing inspections keep their original template.');}
if(a.type==='template-field'){if(!can(s,'manager')||!s.templateDraft)return deny('No editable template draft.');const c=s.templateDraft.checks.find(c=>c.id===a.id);if(c)c[a.key]=a.value;return s;}
if(a.type==='template-add'){if(!can(s,'manager')||!s.templateDraft)return deny('Checklist manager access required.');s.templateDraft.checks.push({id:'custom-'+s.templateDraft.version+'-'+(s.templateDraft.checks.length+1)+'-'+s.seq++,title:'',section:'Additional checks',instruction:'',required:true,evidence:false});return s;}
if(a.type==='template-remove'){if(!can(s,'manager')||!s.templateDraft)return deny('Checklist manager access required.');s.templateDraft.checks=s.templateDraft.checks.filter(c=>c.id!==a.id);return s;}
if(a.type==='template-publish'){if(!can(s,'manager')||!s.templateDraft)return deny('Checklist manager access required.');if(!s.templateDraft.checks.length||s.templateDraft.checks.some(c=>!c.title.trim()||!c.instruction.trim()||!c.section.trim()))return deny('Every check needs a title, section and instructions. Keep at least one check.');s.template=copy(s.templateDraft);s.templateDraft=null;return ok('Template v'+s.template.version+' published for future inspections only.');}
if(!o)return deny('Open an inspection first.');
if(a.type==='intake'){if(!can(s,'reception')||!['requested','confirmed','arrived'].includes(o.status))return deny('Reception can edit intake before inspection starts.');const lockedAudience=o.report||o.snapshots.length;for(const key of ['vehicle','vin','mileage','inspectionDate','requestedAt','commissioner','seller','listing','ownerConsent','publicationConsent','matched','planAcknowledged','payment'])if(key in a.values)o[key]=a.values[key];if(!lockedAudience&&a.values.audience)o.audience=a.values.audience;event(s,o,'Intake details saved.');return ok('Intake saved locally.');}
if(a.type==='confirm'){if(!can(s,'reception')||o.status!=='requested')return deny('Only reception can confirm a requested appointment.');if(!o.requestedAt||!o.ownerConsent||!o.planAcknowledged)return deny('Record requested time, owner access authorization and scope acknowledgment first.');o.status='confirmed';o.confirmedAt=o.requestedAt;event(s,o,'Appointment manually confirmed for '+o.confirmedAt+'.');return ok('Appointment confirmed. The car must arrive at the center.');}
if(a.type==='arrive'){if(!can(s,'reception')||o.status!=='confirmed')return deny('Confirm the appointment before recording arrival.');o.status='arrived';o.arrivedAt=o.inspectionDate;event(s,o,'Vehicle arrival recorded at the center.');return ok('Car checked in at the center.');}
if(a.type==='cancel'||a.type==='no-show'){if(!can(s,'reception')||!['requested','confirmed'].includes(o.status))return deny('Only a pending or confirmed appointment can be cancelled or marked no-show.');if(!a.reason?.trim())return deny('Record a reason first.');o.status=a.type==='cancel'?'cancelled':'no-show';event(s,o,o.status+': '+a.reason);return ok('Order status recorded. No refund rule is implied.');}
if(a.type==='start'){if(!can(s,'technician')||o.status!=='arrived')return deny('Technician starts after the car arrives at the center.');o.status='in-progress';o.assignment='Merdan';o.report=reportDraft(s.template,o.pendingSuccessor?o.snapshots.at(-1).version+1:1);if(o.pendingSuccessor){Object.assign(o.report,o.pendingSuccessor);delete o.pendingSuccessor;}o.inspectedAt=o.inspectionDate;s.tab='checklist';event(s,o,'Technician started inspection using template v'+s.template.version+'.');return ok('Checklist pinned. No result defaults to Normal.');}
if(['answer','summary','panel-status','finding-save','finding-remove','photo','photo-remove','sample'].includes(a.type)){
 if(!editable(s,o))return deny('Only the assigned technician can edit an active draft.');const r=o.report;
 if(a.type==='answer'){r.answers[a.id][a.key]=a.value;return s;}
 if(a.type==='summary'){r.summary=a.value;return s;}
 if(a.type==='panel-status'){r.panels[a.id]={status:a.status,reason:a.reason};return ok('Panel assessment recorded. An assessed panel may have zero findings.');}
 if(a.type==='finding-save'){const f=copy(a.finding);if(!PANELS.some(p=>p[0]===f.panel))return deny('Select a named panel.');if(!f.note.trim())return deny('Describe the observation.');if(f.measurement&&!f.method.trim())return deny('A measurement needs its method and unit.');if(f.kind==='history'&&!f.source.trim())return deny('Attributed history needs an identified source.');if(f.id){const i=r.findings.findIndex(x=>x.id===f.id);if(i<0)return deny('Finding unavailable.');f.photos=r.findings[i].photos;r.findings[i]=f;}else{f.id=r.nextFinding++;f.photos=[];r.findings.push(f);}return ok('Finding F'+f.id+' saved. Record panel assessment and evidence before submission.');}
 if(a.type==='finding-remove'){r.findings=r.findings.filter(f=>f.id!==a.id);return ok('Draft finding removed. Issued snapshots remain immutable.');}
 if(a.type==='photo'||a.type==='photo-remove'){const target=a.target==='finding'?r.findings.find(f=>f.id===Number(a.id)):r.answers[a.id];if(!target)return deny('Evidence target unavailable.');if(a.type==='photo'){if(target.photos.length>=4)return deny('Demo limit: four evidence images per item.');target.photos.push({id:(a.target==='finding'?'F':'C')+a.id+'-P'+s.seq++,src:a.src,caption:a.caption||'Local sample image'});}else target.photos=target.photos.filter(p=>p.id!==a.photo);return ok('Evidence updated in browser memory only.');}
 if(a.type==='sample'){if(r.findings.length||Object.values(r.answers).some(a=>a.result))return deny('The training example fills an empty draft only. Existing findings and notes are preserved.');illustrative(s,o);return ok('Illustrative data inserted. Nothing here is a real inspection.');}
}
if(a.type==='submit'){if(!editable(s,o))return deny('Only the assigned technician can submit a draft.');const issues=gate(o);if(issues.length)return deny(issues.length+' items need attention. '+issues[0]);o.report.state='submitted';event(s,o,'Inspection submitted to reviewer.');s.tab='review';return ok('Submitted. Technician editing is locked until returned.');}
if(a.type==='return'){if(!can(s,'reviewer')||o.report?.state!=='submitted')return deny('Only reviewer can return a submitted inspection.');if(!a.reason?.trim())return deny('Record a return reason.');o.report.state='draft';o.report.returnReason=a.reason;event(s,o,'Returned to technician: '+a.reason);return ok('Returned with reason. Same pinned draft is editable by technician.');}
if(a.type==='finalize'){if(!can(s,'reviewer')||o.report?.state!=='submitted')return deny('Only reviewer can finalize a submitted inspection.');const issues=gate(o);if(issues.length)return deny('Cannot finalize: '+issues[0]);const r=o.report;const snap={id:o.id+'-v'+r.version,orderId:o.id,version:r.version,mode:r.mode,reason:r.reason,parent:r.parent,vehicle:o.vehicle,vin:o.vin,mileage:o.mileage,inspectionDate:o.inspectionDate,center:o.center,audience:o.audience,commissioner:o.commissioner,listing:o.listing,matched:o.matched,publicationConsent:o.publicationConsent,template:copy(r.template),answers:copy(r.answers),panels:copy(r.panels),findings:copy(r.findings),summary:r.summary,reviewedBy:'Aýna · demo reviewer',pdf:'pending',withdrawn:false};o.snapshots.push(snap);o.report.state='finalized';o.status='completed';event(s,o,'Finalized immutable snapshot '+snap.id+'. Audience: '+snap.audience+'. PDF pending.');s.tab='delivery';return ok('Snapshot finalized. PDF readiness is a separate step.');}
if(a.type==='pdf'){if(!can(s,'reviewer'))return deny('Reviewer simulates artifact generation.');const sn=o.snapshots.find(x=>x.id===a.id);if(!sn)return deny('Snapshot unavailable.');sn.pdf=a.value;event(s,o,'PDF '+a.value+' for '+sn.id+'. Snapshot findings unchanged.');return ok(a.value==='ready'?'Demo artifact marked ready. Print view uses this exact snapshot.':a.value==='failed'?'Generation failure simulated. Retry keeps the same report version.':'Retry queued for the same snapshot.');}
if(a.type==='successor'){if(!can(s,'reviewer')||!o.snapshots.length||o.report?.state!=='finalized')return deny('Reviewer creates a successor only after finalization.');if(!a.reason?.trim())return deny('Record a correction or reinspection reason.');const prior=o.snapshots.at(-1);let r;if(a.mode==='correction'){r={...copy(o.report),state:'draft',version:prior.version+1,reason:a.reason,mode:'correction',parent:prior.id,returnReason:''};}else{if(!a.date||!String(a.mileage).trim()||Number(a.mileage)<Number(prior.mileage))return deny('New inspection needs a date and non-decreasing mileage.');o.inspectionDate=a.date;o.mileage=String(a.mileage);o.requestedAt=a.date+'T10:00';o.confirmedAt='';o.arrivedAt='';o.inspectedAt='';o.ownerConsent=false;o.planAcknowledged=false;o.publicationConsent=false;o.matched=false;o.payment='not-recorded';o.pendingSuccessor={reason:a.reason,mode:'reinspection',parent:prior.id};o.report=null;o.assignment='';o.status='requested';event(s,o,'New physical inspection requested: '+a.reason);s.tab='intake';return ok('Reinspection request created. Reception must confirm a new appointment and record arrival. Earlier snapshots are preserved.');}o.report=r;o.status='in-progress';o.assignment='Merdan';event(s,o,(a.mode==='correction'?'Editorial correction':'New physical inspection')+' draft started: '+a.reason);s.tab='checklist';return ok('Successor draft created. Previous snapshot and audience preserved. Technician continues the draft.');}
if(a.type==='withdraw'){if(!can(s,'reviewer'))return deny('Reviewer capability required.');if(!a.reason?.trim())return deny('Record a withdrawal reason.');const sn=o.snapshots.find(x=>x.id===a.id);if(!sn)return deny('Snapshot unavailable.');sn.withdrawn=true;sn.withdrawReason=a.reason;event(s,o,'Withdrawn '+sn.id+': '+a.reason);return ok('Demo withdrawal recorded. Previously exported copies cannot be revoked. Exact withdrawal policy remains open.');}
