const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const $=id=>document.getElementById(id);
const tag=(text,tone='')=>`<span class="tag ${tone}">${esc(text)}</span>`;
const btn=(action,label,extra='',disabled=false,primary=false)=>`<button data-action="${action}" ${extra} ${disabled?'disabled':''} class="${primary?'primary':''}">${label}</button>`;
function dispatch(a,renderNow=true){state=reduce(state,a);if(renderNow)render();}
function field(label,name,value,type='text',disabled=false,extra=''){return `<div class="field"><label for="${name}">${label}</label><input id="${name}" name="${name}" type="${type}" value="${esc(value)}" ${disabled?'disabled':''} ${extra}></div>`;}
function check(label,name,value,disabled=false){return `<label class="check-label"><input name="${name}" type="checkbox" ${value?'checked':''} ${disabled?'disabled':''}><span>${label}</span></label>`;}
function resultOptions(value){return `<option value="">Choose result</option>`+Object.entries(RESULTS).map(([k,v])=>`<option value="${k}" ${value===k?'selected':''}>${v}</option>`).join('');}
function photoBlock(target,id,photos,edit){return `<div class="evidence">${photos.map(p=>`<figure><img src="${esc(p.src)}" alt="${esc(p.caption)}"><figcaption>${esc(p.id)} · ${esc(p.caption)}</figcaption>${edit?btn('photo-remove','Remove',`data-target="${target}" data-id="${id}" data-photo="${esc(p.id)}"`):''}</figure>`).join('')}</div>${edit?`<label class="small" for="photo-${target}-${id}">Add local sample image · max 5 MB, 4 per item<input id="photo-${target}-${id}" type="file" accept="image/jpeg,image/png,image/webp" data-photo-target="${target}" data-photo-id="${id}"></label>`:''}`;}
function svgFor(view,findings=[],interactive=false){let svg=VEHICLE_VIEWS[view];const panelTargets=interactive?PANELS.filter(p=>p[3]===view).map(p=>`<a href="#panel-form" data-select-panel="${p[0]}" aria-label="Select ${p[1]}"><circle cx="${p[4]}" cy="${p[5]}" r="27" fill="${state.panel===p[0]?'#2563eb15':'transparent'}" stroke="${state.panel===p[0]?'#2563eb':'none'}" stroke-width="1" stroke-dasharray="3 3"/></a>`).join(''):'';const marks=findings.filter(f=>f.view===view).map(f=>{const p=PANELS.find(p=>p[0]===f.panel);if(!p)return '';const x=p[4],y=p[5];let fill=f.severity==='fault'?'#b33c0f':f.kind==='repair'?'#926000':'#2563eb';const g=`<circle cx="${x}" cy="${y}" r="13" fill="${fill}" stroke="white" stroke-width="2"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="12" font-family="GeistMono,monospace" fill="white">${f.id}</text>`;return interactive?`<a href="#finding-${f.id}" data-edit-finding="${f.id}" aria-label="Edit finding F${f.id}"><circle cx="${x}" cy="${y}" r="40" fill="transparent"/>${g}</a>`:g;}).join('');svg=svg.replace('</svg>',panelTargets+marks+'</svg>');return svg;}
function overviewState(){const o=current();return `<div class="state-grid"><div><strong>Workspace</strong><p>${esc(NAMES[state.role])}</p><p>Capability ${state.active?'active':'removed'}</p><p>Published template v${state.template.version}</p></div><div><strong>Selected order</strong><p>${o?esc(o.id+' · '+o.status):'None'}</p><p>${o?'Audience: '+esc(o.audience):''}</p><p>${o?'Assigned: '+esc(o.assignment||'Unassigned'):''}</p></div><div><strong>Report and evidence</strong><p>${o?.report?esc(o.report.state+' · v'+o.report.version+' · template v'+o.report.template.version):'No report draft'}</p><p>${o?.report?o.report.findings.length+' body findings · '+Object.values(o.report.answers).filter(a=>a.result).length+'/'+o.report.template.checks.length+' checks answered':''}</p><p>${o?o.snapshots.length+' immutable snapshots':''}</p></div></div><button class="quiet" data-action="access">${state.active?'Simulate staff access removal':'Restore demo staff access'}</button><p class="small">This inspector is a demonstration tool, not a customer or staff production feature.</p>`;}
function queue(){if(state.role==='manager')return '<div class="notice">Checklist manager handles form versions. Open Checklist templates to continue.</div>';const orders=state.orders.filter(o=>state.filter==='all'||(state.filter==='review'?o.report?.state==='submitted':o.status===state.filter));return `<div class="head"><div><h1>Appointments & inspections</h1><p class="muted">One center in Aşgabat. Requests are manually confirmed.</p></div>${btn('new','New request','',!can(state,'reception'),true)}</div><div class="filters">${[['all','All'],['requested','Requested'],['confirmed','Confirmed'],['arrived','At center'],['in-progress','In progress'],['review','Needs review'],['completed','Completed']].map(([k,v])=>`<button data-filter="${k}" aria-pressed="${state.filter===k}">${v}</button>`).join('')}</div>${!state.orders.length?`<div class="group empty"><h2>Start with a center request</h2><p class="muted">Reception records the customer, vehicle, audience and owner authorization.</p><div class="actions">${btn('new','Create request','',!can(state,'reception'),true)}${btn('page-guide','Try a guided walkthrough')}</div></div>`:`<div class="group flat">${orders.length?orders.map(o=>`<div class="row"><div><strong>${esc(o.vehicle)}</strong><p class="mono">${esc(o.id)} · ${esc(o.requestedAt.replace('T',' '))}</p><p class="small muted">${esc(o.commissioner)} · ${o.audience==='private'?'Buyer-private':'Public listing report'}</p></div>${tag(o.report?.state==='submitted'?'Needs review':o.status,o.report?.state==='submitted'?'amber':'')}${btn('open','Open',`data-id="${o.id}"`)}</div>`).join(''):'<div class="empty">No orders in this view.</div>'}</div>`}`;}
function intake(o){const edit=can(state,'reception')&&['requested','confirmed','arrived'].includes(o.status);return `<div class="split"><form id="intake-form" class="group"><h2>Vehicle and request</h2><p class="small muted">Fictional demo data only. Do not enter real personal information.</p><div class="fields">${field('Vehicle','vehicle',o.vehicle,'text',!edit)}${field('Vehicle ID / VIN','vin',o.vin,'text',!edit)}${field('Recorded mileage · km','mileage',o.mileage,'number',!edit,'min="0"')}${field('Inspection date · center local date','inspectionDate',o.inspectionDate,'date',!edit)}${field('Requested time · center local time','requestedAt',o.requestedAt,'datetime-local',!edit)}<div class="field"><label for="audience">Report audience</label><select id="audience" name="audience" ${!edit||o.report?'disabled':''}><option value="private" ${o.audience==='private'?'selected':''}>Buyer-private</option><option value="public" ${o.audience==='public'?'selected':''}>Seller / dealer public listing</option></select></div>${field('Commissioner','commissioner',o.commissioner,'text',!edit)}${field('Vehicle owner / seller','seller',o.seller,'text',!edit)}${field('Listing reference · if applicable','listing',o.listing,'text',!edit)}<div><label for="payment">At-center payment record</label><select id="payment" name="payment" ${!edit?'disabled':''}>${[['not-recorded','Not recorded'],['due-at-center','Due at center'],['recorded-paid','Payment recorded · demo']].map(([v,t])=>`<option value="${v}" ${o.payment===v?'selected':''}>${t}</option>`).join('')}</select></div></div><h3 style="margin-top:24px">Authorization and scope</h3>${check('Vehicle owner authorizes physical inspection at the center.','ownerConsent',o.ownerConsent,!edit)}${check('Customer acknowledges included scope and limits. Price / duration must be agreed before a real booking.','planAcknowledged',o.planAcknowledged,!edit)}${check('Seller / dealer authorizes complete public publication. Required only for public reports.','publicationConsent',o.publicationConsent,!edit)}${check('Staff explicitly matched this vehicle to the listing. Required only for public attachment.','matched',o.matched,!edit)}<div class="actions"><button class="primary" ${!edit?'disabled':''}>Save intake</button></div><p class="sticky-note">Save changes before confirming or checking in. Private report access never follows listing ownership.</p></form><div><div class="group"><h2>Center workflow</h2><p>${tag(o.status)}</p><p class="small muted">${o.confirmedAt?'Confirmed: '+esc(o.confirmedAt.replace('T',' ')):'No confirmed appointment yet.'}</p><p class="small">Assigned technician: ${esc(o.assignment||'Unassigned')}</p><div class="actions">${btn('confirm','Confirm appointment','',!can(state,'reception')||o.status!=='requested',true)}${btn('arrive','Record vehicle arrival','',!can(state,'reception')||o.status!=='confirmed')}${btn('start','Start inspection','',!can(state,'technician')||o.status!=='arrived',true)}</div><div class="actions">${btn('cancel-modal','Cancel request','',!can(state,'reception')||!['requested','confirmed'].includes(o.status))}${btn('noshow-modal','Mark no-show','',!can(state,'reception')||o.status!=='confirmed')}</div></div><div class="notice"><strong>${o.audience==='private'?'Buyer-private report':'Public listing report'}</strong><p style="margin-top:8px">${o.audience==='private'?'Only the commissioning buyer receives this report. The seller and another buyer do not gain access because they know the car or report number.':'Publication requires a vehicle match and explicit permission. Every published finding is included; sellers cannot choose only favorable results.'}</p></div>${eventList(o)}</div></div>`;}
function eventList(o){return `<div class="group"><h3>Activity</h3><ul class="timeline">${o.events.slice().reverse().map(e=>`<li><strong class="small">${esc(e.actor)}</strong><p class="small muted">${esc(e.text)}</p></li>`).join('')}</ul></div>`;}
function checklist(o){const r=o.report;if(!r)return `<div class="group empty"><h2>Inspection has not started</h2><p>Record arrival, then switch to Technician and start inspection.</p></div>`;const edit=editable(state,o),sections=[...new Set(r.template.checks.map(c=>c.section))];return `<div class="head"><div><h2>Inspection checklist</h2><p class="small muted">Template v${r.template.version} pinned · ${Object.values(r.answers).filter(a=>a.result).length}/${r.template.checks.length} answered</p></div>${btn('sample','Fill illustrative example','',!edit)}</div>${r.returnReason?`<div class="notice warning"><strong>Reviewer returned this draft</strong><p style="margin-top:8px">${esc(r.returnReason)}</p></div>`:''}${!edit?'<div class="notice">Read-only in this role or report state. Assigned technician can edit an active draft.</div>':''}<div class="group"><label for="summary">Summary, important faults and inspection limits</label><textarea id="summary" data-summary ${!edit?'disabled':''}>${esc(r.summary)}</textarea><p class="small muted" style="margin-top:8px">No overall score, safety guarantee or default Normal. Every check needs an explicit result.</p></div>${sections.map(section=>`<details class="group" open><summary><strong>${esc(section)}</strong></summary>${r.template.checks.filter(c=>c.section===section).map(c=>{const a=r.answers[c.id];return `<section class="section-row"><h3>${esc(c.title)}</h3><p>${esc(c.instruction)}</p><div class="check-fields"><div><label for="answer-${c.id}">Result</label><select id="answer-${c.id}" data-answer="${c.id}" ${!edit?'disabled':''}>${resultOptions(a.result)}</select></div><div><label for="note-${c.id}">Observation or reason · required unless Normal</label><textarea id="note-${c.id}" data-note="${c.id}" ${!edit?'disabled':''}>${esc(a.note)}</textarea></div></div>${c.evidence?'<p class="small">Evidence requested by this template.</p>':''}${photoBlock('check',c.id,a.photos,edit)}<label for="missing-${c.id}" class="small">If required evidence is unavailable, explain why</label><input id="missing-${c.id}" data-missing-check="${c.id}" value="${esc(a.noEvidence)}" ${!edit?'disabled':''}></section>`;}).join('')}</details>`).join('')}<div class="actions">${btn('save-draft','Save draft in demo','',!edit)}${btn('go-body','Continue to body map','',false,true)}</div>`;}
function panelName(id){return PANELS.find(p=>p[0]===id)?.[1]||id;}
function body(o){const r=o.report;if(!r)return '<div class="group">Start the inspection before recording body findings.</div>';const edit=editable(state,o);const panel=PANELS.find(p=>p[0]===state.panel)||PANELS[0];const assessed=r.panels[panel[0]];return `<div class="head"><div><h2>Body map & findings</h2><p class="small muted">${Object.values(r.panels).filter(p=>p.status).length}/${PANELS.length} panel assessments · ${r.findings.length} findings</p></div>${btn('sample','Fill illustrative example','',!edit)}</div><div class="body-layout"><div><div class="group"><div class="map-tabs" role="tablist" aria-label="Vehicle view">${Object.entries(VIEW_LABELS).map(([k,v])=>`<button role="tab" data-view="${k}" aria-selected="${state.view===k}">${v}</button>`).join('')}</div><div class="vehicle ${state.view}">${svgFor(state.view,r.findings,edit)}</div><div class="map-caption"><strong>${VIEW_LABELS[state.view]} view</strong><span class="muted">${state.view==='top'?'Front ↑':state.view==='left'||state.view==='right'?'Front faces left':''}</span></div><p class="small muted" style="margin-top:16px">Generic sedan geometry, not an exact model map. Left / right follow the vehicle's direction of travel. Blank space is not a pass.</p><div class="legend"><span>Number = finding ID</span><span>Repair evidence ≠ accident history</span></div></div><div class="group"><h3>Choose a named panel</h3><p class="small muted">This list works even when a drawing does not fit the vehicle. Panel identity is the record; drawing position is a guide.</p><div class="panel-choice">${PANELS.map(p=>`<button data-panel="${p[0]}" aria-pressed="${state.panel===p[0]}">${esc(p[1])}${tag(r.panels[p[0]].status||'Unassessed')}</button>`).join('')}</div></div></div><div><form class="group" id="panel-form"><h3>${esc(panel[1])}</h3><label for="panel-status">Explicit assessment</label><select id="panel-status" name="status" ${!edit?'disabled':''}><option value="">Unassessed</option><option value="assessed" ${assessed.status==='assessed'?'selected':''}>Assessed · findings recorded below, if any</option><option value="unchecked" ${assessed.status==='unchecked'?'selected':''}>Not checked</option></select><label for="panel-reason" style="margin-top:12px">Reason / assessment note</label><textarea id="panel-reason" name="reason" ${!edit?'disabled':''}>${esc(assessed.reason)}</textarea><div class="actions"><button class="primary" ${!edit?'disabled':''}>Save panel assessment</button>${btn('finding-new','Add finding',`data-panel="${panel[0]}"`,!edit)}</div><p class="sticky-note">An assessed panel can have zero findings. An untouched panel remains unassessed.</p></form><div class="group flat">${r.findings.length?r.findings.map(f=>`<div class="row" id="finding-${f.id}"><span class="marker-id">${f.id}</span><div><strong>${esc(panelName(f.panel))}</strong><p class="small">${esc(KINDS[f.kind])} · ${esc(f.severity)}</p><p class="small muted">${esc(f.note)}</p>${f.measurement?`<p class="mono">${esc(f.measurement+' '+f.unit)}</p>`:''}<p class="small muted">${f.photos.length} image(s) · ${f.noEvidence?'missing evidence explained':'evidence check pending'}</p></div>${btn('finding-edit','Edit',`data-id="${f.id}"`,!edit)}</div>`).join(''):'<div class="row"><p class="muted">No findings recorded. This does not mean all panels were checked.</p></div>'}</div></div></div><div class="actions">${btn('go-review','Continue to review','',false,true)}</div>`;}
function reportReader(sn,{draft=false}={}){const title=draft?'DRAFT · Staff preview':sn.withdrawn?'WITHDRAWN · Historical report':'Inspection report';return `<article class="snapshot"><p class="print-only">Carberk · LOCAL DEMONSTRATION · FICTIONAL DATA</p><h1>${title}</h1><p class="vehicle-name">${esc(sn.vehicle)}</p><p class="mono" style="margin-top:12px">${esc(sn.id||'Draft')} · ${esc(sn.audience==='private'?'Buyer-private':'Public listing report')} · checklist v${sn.template.version}</p><div class="notice warning" style="margin-top:20px">Fictional demonstration. No physical vehicle inspection took place. This is not a warranty, real issued report or approved service scope.${draft?' DRAFT: not finalized and not deliverable.':''}${sn.withdrawn?' WITHDRAWN: '+esc(sn.withdrawReason):''}</div>${sn.parent?`<p class="small">${sn.mode==='correction'?'Editorial correction. Original observation date retained.':'New physical inspection.'} Previous snapshot: ${esc(sn.parent)}. Reason: ${esc(sn.reason)}</p>`:''}<dl><div><dt>Inspection date</dt><dd class="mono">${esc(sn.inspectionDate)}</dd></div><div><dt>Recorded mileage</dt><dd class="mono">${esc(sn.mileage)} km</dd></div><div><dt>Center</dt><dd>${esc(sn.center)}</dd></div><div><dt>Vehicle identity · masked demo</dt><dd class="mono">…${esc(sn.vin.slice(-4))}</dd></div><div><dt>Report version</dt><dd class="mono">v${sn.version}</dd></div><div><dt>Reviewed by</dt><dd>${esc(sn.reviewedBy||'Not finalized')}</dd></div></dl><h2>Summary & important faults</h2><p>${esc(sn.summary)}</p><section class="report-section"><h2>Body map</h2><div class="map-tabs reader-tabs no-print" role="tablist" aria-label="Report vehicle views">${Object.entries(VIEW_LABELS).map(([k,v])=>`<button data-reader-view="${k}" role="tab" aria-selected="${(state.readerView||'left')===k}">${v}</button>`).join('')}</div><div class="report-map">${['left','right','top','front','rear'].map(v=>`<figure class="reader-figure ${(state.readerView||'left')===v?'reader-selected':''}"><figcaption>${VIEW_LABELS[v]} ${v==='top'?'· Front ↑':v==='left'||v==='right'?'· Front ←':''}</figcaption>${svgFor(v,sn.findings)}</figure>`).join('')}</div><p class="small muted" style="margin-top:16px">Generic sedan drawing, not a model-specific panel map. Blank space does not mean Normal. Findings and explicit panel assessments are listed below.</p><h3 style="margin-top:24px">Panel assessment record</h3>${PANELS.map(p=>`<div class="result"><span class="tag">${esc(sn.panels[p[0]]?.status||'Unassessed')}</span><strong class="small">${esc(p[1])}</strong>${sn.panels[p[0]]?.reason?`<p>${esc(sn.panels[p[0]].reason)}</p>`:''}</div>`).join('')}<h3 style="margin-top:24px">Numbered findings</h3>${sn.findings.length?sn.findings.map(f=>`<div class="result"><span class="tag ${f.severity==='fault'?'fault':''}">${esc(f.severity)}</span><h3>F${f.id} · ${esc(panelName(f.panel))}</h3><p><strong>${esc(KINDS[f.kind])}</strong> · ${esc(f.note)}</p>${f.measurement?`<p><span class="mono">${esc(f.measurement+' '+f.unit)}</span> · ${esc(f.method)}</p>`:''}${f.source?`<p>Attributed source: ${esc(f.source)}</p>`:''}${photoBlock('finding',f.id,f.photos,false)}${f.noEvidence?`<p>Evidence limitation: ${esc(f.noEvidence)}</p>`:''}</div>`).join(''):'<p>No body findings recorded. Refer to the explicit panel assessment list.</p>'}</section><section class="report-section"><h2>Inspection checklist</h2>${sn.template.checks.map(c=>{const a=sn.answers[c.id];return `<div class="result"><span class="tag ${a.result==='fault'?'fault':''}">${esc(RESULTS[a.result]||'Unanswered')}</span><h3>${esc(c.title)}</h3><p class="muted">${esc(c.instruction)}</p>${a.note?`<p>${esc(a.note)}</p>`:''}${photoBlock('check',c.id,a.photos,false)}${a.noEvidence?`<p>Evidence limitation: ${esc(a.noEvidence)}</p>`:''}</div>`;}).join('')}</section><p class="small muted" style="margin-top:24px">Point-in-time observations only. Not checked and not applicable are not passed checks. Repaint evidence alone does not establish accident history. No aggregate grade, guarantee or ranking boost. No customer contact, booking conversation or internal reviewer note is included in this report.</p></article>`;}
function draftSnapshot(o){return {...copy(o.report),id:o.id+'-DRAFT-v'+o.report.version,vehicle:o.vehicle,vin:o.vin,mileage:o.mileage,inspectionDate:o.inspectionDate,center:o.center,audience:o.audience,reviewedBy:'Not finalized'};}
function review(o){if(!o.report)return '<div class="group">No inspection draft yet.</div>';const r=o.report,issues=gate(o);if(state.previewDraft)return `<div class="actions no-print" style="margin-bottom:24px">${btn('preview-close','Back to review')}${btn('print-draft','Print draft · demo only')}</div>${reportReader(draftSnapshot(o),{draft:true})}`;return `<div class="head"><div><h2>Completeness & review</h2><p class="small muted">${esc(r.state)} · ${r.mode==='correction'?'Editorial correction':r.mode==='reinspection'?'New physical inspection':'Initial physical inspection'}</p></div>${btn('preview-draft','Open staff draft preview')}</div><div class="split"><div><div class="group"><h3>Readiness</h3>${issues.length?`<p class="danger">${issues.length} item(s) need attention.</p><ul class="tick-list">${issues.slice(0,15).map(i=>`<li>${esc(i)}</li>`).join('')}</ul>${issues.length>15?`<p class="small muted">And ${issues.length-15} more. Answer all checks and assess every panel.</p>`:''}`:'<p>All prototype completeness checks passed. A qualified reviewer must still assess the actual findings.</p>'}<div class="actions">${btn('submit','Submit to reviewer','',!editable(state,o),true)}${btn('return-modal','Return with reason','',!can(state,'reviewer')||r.state!=='submitted')}${btn('finalize','Finalize snapshot','',!can(state,'reviewer')||r.state!=='submitted'||!!issues.length,true)}</div></div><div class="group"><h3>Summary</h3><p>${esc(r.summary||'Not entered')}</p><h3 style="margin-top:20px">Important findings</h3>${r.findings.filter(f=>f.severity==='fault').map(f=>`<p><strong>F${f.id} · ${esc(panelName(f.panel))}</strong><br>${esc(f.note)}</p>`).join('')||'<p class="muted">No body fault recorded. Check the complete mechanical results too.</p>'}<p class="small muted">Draft preview includes every check and finding. Reviewer return notes remain staff-only.</p></div></div><div><div class="notice"><strong>Review gates in this demo</strong><ul><li>Only the separate Reviewer role finalizes.</li><li>Public audience requires listing match and publication permission.</li><li>All checks and panels need explicit results.</li><li>Missing evidence needs an explanation where required.</li><li>Finalization freezes report content. PDF readiness remains separate.</li></ul></div>${eventList(o)}</div></div>`;}
function authorized(sn,viewer){if(sn.withdrawn)return false;if(sn.audience==='public')return sn.matched&&sn.publicationConsent;if(viewer==='commissioner')return true;return false;}
function delivery(o){if(!o.snapshots.length)return '<div class="group empty"><h2>No finalized report</h2><p>Technician submits a complete inspection, then Reviewer finalizes it.</p></div>';const sn=o.snapshots.find(x=>x.id===state.selectedSnapshot)||o.snapshots.at(-1);const allow=authorized(sn,state.viewer);const latest=o.snapshots.at(-1);const staff=state.active;return `<div class="head no-print"><div><h2>Delivery & reader</h2><p class="mono">${esc(sn.id)} · PDF ${esc(sn.pdf)}</p></div><div><label for="snapshot-picker">Snapshot</label><select id="snapshot-picker">${o.snapshots.map(x=>`<option value="${x.id}" ${x.id===sn.id?'selected':''}>${x.id}${x.withdrawn?' · withdrawn':''}</option>`).join('')}</select></div></div><div class="group no-print"><div class="fields"><div><label for="reader-actor">Simulate a recipient</label><select id="reader-actor">${[['commissioner','Commissioning customer · Buyer A / seller'],['buyer-b','Unrelated Buyer B'],['seller','Vehicle seller / dealer'],['public','Anonymous reader']].map(([v,t])=>`<option value="${v}" ${state.viewer===v?'selected':''}>${t}</option>`).join('')}</select></div><div><h3>Access result</h3><p>${allow?tag(sn.audience==='private'?'Private authorized copy':'Public complete copy','blue'):tag('No accessible report','fault')}</p><p class="small muted">This is a local audience simulation, not a secure link or real authorization.</p></div></div>${staff?`<div class="actions">${btn('pdf-fail','Simulate PDF failure',`data-id="${sn.id}"`,!can(state,'reviewer'))}${btn('pdf-retry','Retry same artifact',`data-id="${sn.id}"`,!can(state,'reviewer'))}${btn('pdf-ready','Mark demo PDF ready',`data-id="${sn.id}"`,!can(state,'reviewer'),true)}</div>`:''}</div>${sn.id!==latest.id?`<div class="notice no-print">Historical version. Latest finalized snapshot is ${esc(latest.id)}. Old downloaded copies retain their original content.</div>`:''}${!allow?'<div class="group empty"><h2>No accessible report</h2><p>This recipient cannot access this report or its evidence. Private reports are not disclosed through listing ownership or a guessed ID.</p><p class="small muted">In production, the public route must also avoid confirming that a private report exists.</p></div>':`${sn.pdf!=='ready'?`<div class="notice ${sn.pdf==='failed'?'warning':''} no-print">${sn.pdf==='failed'?'PDF generation failed. The report snapshot is unchanged. Retry does not create a new report version.':'PDF generation pending. No download is ready yet.'}</div>`:`<div class="actions export-actions no-print" style="margin-bottom:24px">${btn('print-final','Print / save demo PDF',`data-id="${sn.id}"`,false,true)}</div>`}${reportReader(sn)}`}`;}
function history(o){return `<div class="head"><div><h2>Report history</h2><p class="small muted">Issued snapshots are preserved. Corrections do not become new physical observations.</p></div></div>${o.snapshots.length?`<div class="group flat">${o.snapshots.slice().reverse().map(sn=>`<div class="row"><div><strong>${esc(sn.id)}</strong><p class="small">${esc(sn.mode)} · ${esc(sn.inspectionDate)} · ${esc(sn.mileage)} km</p><p class="small muted">Template v${sn.template.version} · ${esc(sn.audience)} · ${sn.withdrawn?'withdrawn':sn.pdf+' PDF'}</p>${sn.reason?`<p class="small">Reason: ${esc(sn.reason)}</p>`:''}</div>${btn('snapshot-open','View',`data-id="${sn.id}"`)}</div>`).join('')}</div><div class="group"><h3>Start a successor</h3><p class="small muted">Editorial correction retains the inspection date, mileage and audience. Reinspection starts a new checklist using the current template and requires a new physical date and mileage. The original report remains in history.</p><div class="actions">${btn('correction-modal','Create correction','',!can(state,'reviewer')||o.report?.state!=='finalized')}${btn('reinspection-modal','Start reinspection','',!can(state,'reviewer')||o.report?.state!=='finalized')}${btn('withdraw-modal','Withdraw latest report','',!can(state,'reviewer'))}</div><p class="sticky-note">Exact withdrawal, previous-version visibility and customer dispute policies remain open. This demo preserves the original audience and does not enable private-to-public conversion.</p></div>`:'<div class="group">No finalized snapshots yet.</div>'}${eventList(o)}`;}
function inspection(){if(state.role==='manager')return '<div class="notice">Checklist manager cannot browse inspection records in this role simulation.</div>';const o=current();if(!o)return '<div class="group">No inspection selected.</div>';const tabs=[['intake','Intake'],['checklist','Checklist'],['body','Body map'],['review','Review'],['delivery','Delivery'],['history','History']];return `${btn('back-queue','← Appointments','','',false)}<div class="head"><div><h1>${esc(o.vehicle)}</h1><p class="mono">${esc(o.id)} · ${esc(o.audience)} · ${esc(o.status)}${o.report?' · report '+esc(o.report.state):''}</p></div>${!state.active?tag('Staff access removed','fault'):''}</div><div class="step-nav" aria-label="Inspection steps">${tabs.map(([k,v])=>`<button data-tab="${k}" aria-current="${state.tab===k?'page':'false'}">${v}</button>`).join('')}</div>${!state.active?'<div class="notice warning">Demo staff capability is removed. Internal inspection editing and draft access are unavailable. Restore access through the demo state inspector.</div>':(['checklist','body','review','delivery','history'].includes(state.tab)&&!['technician','reviewer'].includes(state.role))?'<div class="notice">This demo role handles intake or templates. Switch to the assigned Technician or Reviewer to access inspection results.</div>':({intake:()=>intake(o),checklist:()=>checklist(o),body:()=>body(o),review:()=>review(o),delivery:()=>delivery(o),history:()=>history(o)}[state.tab]||(()=>''))()}`;}
function templates(){const d=state.templateDraft;return `<div class="head"><div><h1>Checklist templates</h1><p class="muted">One service plan. Started inspections keep their pinned version.</p></div>${btn('template-clone','Prepare next version','',!can(state,'manager')||!!d,true)}</div><div class="notice">Template structure and mechanical service capability are separate approvals. The 36 draft Turkmen checks are for mechanic review. They are not a promise that the center performs every test.</div><div class="group"><h2>Published v${state.template.version}</h2><p>${state.template.checks.length} checks · ${state.orders.filter(o=>o.report?.template.version===state.template.version).length} current inspection draft(s) pinned</p><p class="small muted">Publishing a new version changes future starts only. Historical snapshots keep their original titles, instructions, results and evidence.</p></div>${d?`<div class="group"><h2>Draft v${d.version}</h2>${d.checks.map(c=>`<section class="template-item"><p class="mono">${esc(c.id)}</p><div class="fields">${field('Section','section-'+c.id,c.section,'text',!can(state,'manager'),`data-template="${c.id}" data-key="section"`)}${field('Check name','title-'+c.id,c.title,'text',!can(state,'manager'),`data-template="${c.id}" data-key="title"`)}<div><label for="instruction-${c.id}">Instructions, method and scope</label><textarea id="instruction-${c.id}" data-template="${c.id}" data-key="instruction" ${!can(state,'manager')?'disabled':''}>${esc(c.instruction)}</textarea></div></div><label class="check-label"><input type="checkbox" data-template="${c.id}" data-key="evidence" ${c.evidence?'checked':''} ${!can(state,'manager')?'disabled':''}><span>Ask for evidence or an explicit missing-evidence explanation.</span></label>${btn('template-remove','Remove from this draft',`data-id="${c.id}"`,!can(state,'manager'))}</section>`).join('')}<div class="actions">${btn('template-add','Add a check','',!can(state,'manager'))}${btn('template-publish','Publish template v'+d.version,'',!can(state,'manager'),true)}</div></div>`:`<div class="group flat">${state.template.checks.map(c=>`<div class="row"><div><strong>${esc(c.title)}</strong><p class="small muted">${esc(c.instruction)}</p></div></div>`).join('')}</div>`}`;}
function archive(){if(!state.active||!['technician','reviewer'].includes(state.role))return '<div class="notice">Report archive access is limited to Technician and Reviewer in this demo. Reception handles appointments; Checklist manager handles templates.</div>';const rows=state.orders.flatMap(o=>o.snapshots.map(sn=>({o,sn})));return `<div class="head"><div><h1>Report history</h1><p class="muted">All finalized demonstration snapshots, including earlier versions.</p></div></div>${rows.length?`<div class="group flat">${rows.slice().reverse().map(({o,sn})=>`<div class="row"><div><strong>${esc(sn.vehicle)}</strong><p class="mono">${esc(sn.id)} · template v${sn.template.version}</p><p class="small muted">${esc(sn.audience)} · ${esc(sn.mode)} · ${sn.withdrawn?'withdrawn':sn.pdf}</p></div>${btn('archive-open','Open history',`data-id="${o.id}"`)}</div>`).join('')}</div>`:'<div class="group empty"><h2>No finalized reports</h2><p>Complete a guided walkthrough to create an example.</p></div>'}`;}
function guidePage(){return `<h1>Explore the complete flow</h1><p class="muted">Each walkthrough resets fictional data and performs real prototype actions. You can switch roles and explore freely between steps.</p><div class="group" style="margin-top:24px">${Object.entries(GUIDES).map(([id,g])=>`<section class="section-row"><h3>${g.title}</h3><p>${g.description}</p>${btn('guide-start','Start walkthrough',`data-id="${id}"`,false,true)}</section>`).join('')}</div><div class="notice">Guided examples use an explicit “Fill illustrative example” action. It is a demo convenience, not a proposed auto-pass control for technicians.</div>`;}
function guideBanner(){if(!state.guide)return '';const g=GUIDES[state.guide],i=state.guideStep,step=g.steps[i];return `<section class="guide-box"><div class="guide-step">${esc(g.title)} · ${Math.min(i+1,g.steps.length)} / ${g.steps.length}</div><h3>${step?esc(step.label):'Walkthrough complete'}</h3><p>${step?esc(step.explain):'Explore the screens or restart. All results remain local and fictional.'}</p><div class="actions">${btn('guide-prev','Previous step','',i===0)}${btn('guide-next',step?'Do this step':'Finished','',!step,true)}${btn('guide-restart','Restart')}${btn('guide-exit','Exit guide')}</div></section>`;}
function render(){document.querySelectorAll('[data-page]').forEach(b=>b.setAttribute('aria-current',state.page===b.dataset.page?'page':'false'));$('role').value=state.role;$('feedback').className=state.error?'error':'';$('feedback').textContent=state.message;$('guide-banner').innerHTML=guideBanner();$('screen').innerHTML=!state.active?'<div class="notice warning">Staff access removed in this simulation. Internal records and edits are unavailable. Restore capability below.</div>':state.page==='queue'?queue():state.page==='templates'?templates():state.page==='archive'?archive():state.page==='guide'?guidePage():inspection();$('state').innerHTML=overviewState();const dialog=document.querySelector('[role=dialog]');if(dialog){dialog.querySelector('.modal-feedback')?.remove();if(state.error){const alert=document.createElement('p');alert.className='notice warning modal-feedback';alert.setAttribute('role','alert');alert.textContent=state.message;dialog.querySelector('h2').after(alert);}}}
function modal(title,body){$('modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><h2 id="modal-title">${title}</h2>${body}</section></div>`;const root=$('modal-root');root.querySelector('input,textarea,select,button')?.focus();}
function closeModal(){const previously=$('modal-root').querySelector('[data-action=modal-close]');$('modal-root').innerHTML='';}
function findingModal(id=null,panel=null){const o=current();if(!editable(state,o)){state.message='Assigned technician can edit an active draft.';state.error=true;render();return;}const f=id?copy(o.report.findings.find(f=>f.id===Number(id))):{id:null,panel:panel||state.panel,kind:'damage',severity:'note',note:'',measurement:'',unit:'mm',method:'',source:'',noEvidence:'',photos:[]};if(!f)return;modal(id?'Edit finding F'+id:'Add a finding',`<p class="small muted">Current damage, repair evidence and attributed history are different observations.</p><form id="finding-form" data-id="${f.id||''}"><div class="fields"><div><label for="finding-panel">Named panel</label><select id="finding-panel" name="panel">${PANELS.map(p=>`<option value="${p[0]}" ${f.panel===p[0]?'selected':''}>${p[1]}</option>`).join('')}</select></div><div><label for="kind">Finding type</label><select id="kind" name="kind">${Object.entries(KINDS).map(([k,v])=>`<option value="${k}" ${f.kind===k?'selected':''}>${v}</option>`).join('')}</select></div><div><label for="severity">Outcome</label><select id="severity" name="severity"><option value="note" ${f.severity==='note'?'selected':''}>Note</option><option value="fault" ${f.severity==='fault'?'selected':''}>Fault · priority finding</option></select></div><div class="full"><label for="finding-note">Observation, uncertainty and explanation</label><textarea id="finding-note" name="note" required>${esc(f.note)}</textarea></div>${field('Measurement · optional','measurement',f.measurement,'number',false,'step="any" min="0"')}<div><label for="unit">Unit</label><select id="unit" name="unit">${['mm','µm','bar','%'].map(u=>`<option ${f.unit===u?'selected':''}>${u}</option>`).join('')}</select></div><div class="full">${field('Measurement method · required if a value is entered','method',f.method)}</div><div class="full">${field('Identified history source · required for attributed history','source',f.source)}</div><div class="full"><label for="noEvidence">If photos are missing, explain why</label><textarea id="noEvidence" name="noEvidence">${esc(f.noEvidence)}</textarea></div></div>${id?photoBlock('finding',id,f.photos,true):'<p class="small muted" style="margin-top:16px">Save this finding first, then reopen it to attach images with stable evidence references.</p>'}<div class="actions"><button class="primary">Save finding</button>${btn('modal-close','Cancel')}${id?btn('finding-remove','Remove draft finding',`data-id="${id}"`):''}</div></form>`);}
function newModal(){modal('New inspection request',`<p class="small muted">Manual center booking. No live service or payment is created.</p><form id="new-form"><div class="fields">${field('Vehicle','vehicle','Toyota Camry, 2018')}${field('Vehicle ID · demo','vin','DEMO-VEHICLE-001')}${field('Mileage · km','mileage','128400','number',false,'min="0"')}${field('Proposed inspection date','date','2026-10-14','date')}${field('Requested center time','appointment','2026-10-14T10:00','datetime-local')}<div><label for="new-audience">Audience</label><select id="new-audience" name="audience"><option value="private">Buyer-private</option><option value="public">Public listing report</option></select></div>${field('Commissioner','commissioner','Buyer A · fictional')}${field('Vehicle owner','seller','Showroom · fictional')}${field('Listing reference','listing','DEMO-LISTING-01')}</div><div class="actions"><button class="primary">Create request</button>${btn('modal-close','Cancel')}</div></form>`);}
function reasonModal(action,title){const extra=action==='reinspection-modal'?`<div class="fields">${field('New physical inspection date','date','2026-10-21','date')}${field('New recorded mileage · km','mileage',String(Number(current().mileage)+150),'number',false,'min="0"')}</div>`:'';modal(title,`<form id="reason-form" data-kind="${action}"><label for="reason">Reason</label><textarea id="reason" name="reason" required></textarea>${extra}<div class="actions"><button class="primary">Confirm in demo</button>${btn('modal-close','Cancel')}</div></form>`);}
const step=(label,explain,actions)=>({label,explain,actions});
const startSteps=audience=>[
 step('Reception creates the request','Choose the report audience at intake. A request is not a confirmed appointment.',()=>[{type:'role',value:'reception'},{type:'create',audience,commissioner:audience==='private'?'Buyer A · fictional':'Showroom · fictional'}]),
 step('Record authorization and service scope','Owner physical-access permission is required for both audiences. Public delivery also needs explicit publication permission and a listing match.',()=>[{type:'intake',values:{ownerConsent:true,planAcknowledged:true,publicationConsent:audience==='public',matched:audience==='public',payment:'due-at-center'}}]),
 step('Manually confirm the appointment','Reception confirms the time. The customer brings the vehicle to the center.',()=>[{type:'confirm'}]),
 step('Record arrival at the center','The inspection can start only after the vehicle arrives.',()=>[{type:'arrive'}]),
 step('Technician starts the pinned checklist','Template v1 is copied into the inspection. No check or panel defaults to Normal.',()=>[{type:'role',value:'technician'},{type:'start'}]),
 step('Try an incomplete submission','Attempting to submit a blank inspection must leave the draft editable and explain the missing scope.',()=>[{type:'submit'}]),
 step('Fill the illustrative training example','This explicit demo action creates fictional results, four findings and one labelled evidence placeholder. It is not an auto-pass tool for real staff.',()=>[{type:'sample'},{type:'tab',value:'body'}]),
 step('Inspect the panel record and numbered findings','Panels without physical results are explicitly Not checked with a reason. Finding numbers connect the body view and report.',()=>[{type:'view',value:'right'},{type:'tab',value:'body'}])
];
const finishSteps=[
 step('Technician submits for review','The assigned technician submits the complete draft. Editing locks until the reviewer returns it.',()=>[{type:'role',value:'technician'},{type:'submit'}]),
 step('Reviewer checks the complete draft','A separate demo reviewer inspects completeness, important faults, scope and audience.',()=>[{type:'role',value:'reviewer'},{type:'tab',value:'review'}]),
 step('Finalize the immutable snapshot','Every finding and explicit limitation is frozen. Finalization does not make the PDF ready.',()=>[{type:'finalize'}]),
 step('Simulate a failed PDF job','The snapshot stays intact. The interface must not offer a successful download.',()=>[{type:'pdf',id:current().snapshots.at(-1).id,value:'failed'}]),
 step('Retry and mark the demo artifact ready','The same snapshot is retried. No new report version is created. Browser print is a prototype approximation of the planned server PDF.',()=>[{type:'pdf',id:current().snapshots.at(-1).id,value:'pending'},{type:'pdf',id:current().snapshots.at(-1).id,value:'ready'},{type:'viewer',value:'commissioner'}])
];
const GUIDES={
 public:{title:'Dealer public report',description:'Center intake, full checklist and body findings, independent review, PDF failure/retry and a complete public report.',steps:[...startSteps('public'),...finishSteps,step('An unrelated buyer reads the public report','Buyer B can read the full published snapshot free. The seller cannot choose only favorable findings.',()=>[{type:'viewer',value:'buyer-b'},{type:'tab',value:'delivery'}])]},
 private:{title:'Buyer A and Buyer B',description:'Buyer A commissions a private inspection, declines to buy, and Buyer B asks about the same car.',steps:[...startSteps('private'),...finishSteps,step('Buyer A receives the private copy','Only the commissioning buyer is authorized in this sample. Declining to buy does not publish the report.',()=>[{type:'viewer',value:'commissioner'},{type:'tab',value:'delivery'}]),step('Buyer B asks for the report','Buyer B cannot access the report, PDF or evidence by knowing the vehicle or report ID. They may request a separate inspection.',()=>[{type:'viewer',value:'buyer-b'}]),step('The seller asks for Buyer A’s report','Vehicle ownership and dealership membership do not grant access to a buyer-private report.',()=>[{type:'viewer',value:'seller'}])]},
 returned:{title:'Return to technician',description:'An incomplete or unclear report returns with a reason, resumes the same draft and is reviewed again.',steps:[...startSteps('public'),...finishSteps.slice(0,2),step('Return with an explicit reason','The reviewer does not edit results silently. The same pinned draft returns to the assigned technician.',()=>[{type:'return',reason:'Clarify the tire fault and preserve the explanation for the skipped road test.'}]),step('Technician clarifies and resubmits','Finding identity and template stay unchanged. The earlier return remains in staff activity, not the customer report.',()=>[{type:'role',value:'technician'},{type:'summary',value:current().report.summary+' Reviewer clarification: the tire finding is illustrative and the road test was explicitly not performed.'},{type:'submit'}]),...finishSteps.slice(1)]},
 template:{title:'Checklist version change',description:'Publish a revised template while an inspection is in progress. Earlier drafts and reports must retain the old version.',steps:[...startSteps('public').slice(0,5),step('Manager prepares v2','Started inspection stays pinned to v1. Changes are made in a new template draft.',()=>[{type:'role',value:'manager'},{type:'page',value:'templates'},{type:'template-clone'}]),step('Remove one check in v2 and publish','The old check stays in the started v1 inspection. Removing a check is an explicit illustrative revision, not mechanical approval.',()=>[{type:'template-remove',id:state.templateDraft.checks.at(-1).id},{type:'template-publish'}]),step('Return to the original inspection','It still has all 36 v1 checks. Future inspection starts use the revised published version.',()=>[{type:'role',value:'technician'},{type:'select',id:state.selected,tab:'checklist'},{type:'sample'}]),...finishSteps,step('Create a second appointment','New center intake starts independently of the published report. Both records remain in the queue.',()=>[{type:'role',value:'reception'},{type:'create',audience:'private',vehicle:'Hyundai Sonata, 2020',vin:'DEMO-VEHICLE-002'},{type:'intake',values:{ownerConsent:true,planAcknowledged:true}},{type:'confirm'},{type:'arrive'}]),step('Start using v2','This new inspection uses the 35-check v2 template. The earlier report snapshot retains its original 36 checks.',()=>[{type:'role',value:'technician'},{type:'start'}])]},
 correction:{title:'Correction and reinspection',description:'Preserve an issued snapshot, make an editorial correction, then book a new physical inspection with a fresh checklist.',steps:[...startSteps('public'),...finishSteps,step('Reviewer starts an editorial correction','The first snapshot remains untouched. This successor retains the original audience, inspection date, mileage and checklist.',()=>[{type:'successor',mode:'correction',reason:'Clarify the paint-measurement method; no new physical observation.'}]),step('Technician clarifies the successor','Only the draft changes. The original public snapshot remains available while the correction is reviewed.',()=>[{type:'role',value:'technician'},{type:'summary',value:current().report.summary+' Editorial clarification: 245 µm is a fictional coating-gauge example.'},{type:'submit'}]),step('Reviewer finalizes correction v2','History now preserves v1 and v2. An editorial correction must never look like a fresh inspection.',()=>[{type:'role',value:'reviewer'},{type:'finalize'},{type:'tab',value:'history'}]),step('Request a new physical inspection','Reinspection starts a new appointment workflow, clears old results and requires renewed physical-access authorization.',()=>[{type:'successor',mode:'reinspection',reason:'Vehicle returned to the center after stated repairs.',date:'2026-10-21',mileage:'128550'}]),step('Reception confirms the return visit','A new appointment, permission and vehicle match are recorded. Earlier snapshots keep their original dates and findings.',()=>[{type:'role',value:'reception'},{type:'intake',values:{ownerConsent:true,planAcknowledged:true,publicationConsent:true,matched:true}},{type:'confirm'},{type:'arrive'}]),step('Start the fresh inspection','The latest template is pinned. Checks, panels and findings start empty. No historical result is relabelled as a new observation.',()=>[{type:'role',value:'technician'},{type:'start'},{type:'tab',value:'checklist'}])]},
 access:{title:'Permission removal and cancellations',description:'A removed staff capability cannot continue editing. A no-show or cancelled appointment never becomes a completed inspection.',steps:[...startSteps('private').slice(0,5),step('Remove the technician’s capability','The draft and assignment remain, but protected reads and writes are blocked in this local simulation.',()=>[{type:'access'}]),step('Try to edit with removed access','The action is denied; no checklist outcomes change. Production must enforce this on the server and evidence URLs.',()=>[{type:'sample'}]),step('Restore demo capability','The original draft remains available, with no fabricated results.',()=>[{type:'access'}]),step('Create a separate no-show example','Reception confirms another request. The original inspection stays intact.',()=>[{type:'role',value:'reception'},{type:'create',vehicle:'Kia K5, 2021',vin:'DEMO-NOSHOW'},{type:'intake',values:{ownerConsent:true,planAcknowledged:true}},{type:'confirm'}]),step('Mark the no-show with reason','No report is created. Cancellation and refund terms remain operating-policy decisions.',()=>[{type:'no-show',reason:'Vehicle did not arrive for the confirmed demo appointment.'},{type:'page',value:'queue'}])]} };
function startGuide(id){state=initial();state.guide=id;state.page='guide';render();}
function advanceGuide(){const g=GUIDES[state.guide];if(!g||!g.steps[state.guideStep])return;const actions=g.steps[state.guideStep].actions();for(const a of actions)state=reduce(state,a);state.guideStep++;render();window.scrollTo({top:0});}
function previousGuide(){const id=state.guide,n=Math.max(0,state.guideStep-1);state=initial();state.guide=id;state.page='guide';for(let i=0;i<n;i++){const actions=GUIDES[id].steps[i].actions();for(const a of actions)state=reduce(state,a);state.guideStep++;}render();window.scrollTo({top:0});}
document.addEventListener('click',e=>{const b=e.target.closest('button,[data-edit-finding],[data-select-panel]');if(!b)return;if(b.dataset.page){dispatch({type:'page',value:b.dataset.page});return;}if(b.dataset.tab){state.previewDraft=false;dispatch({type:'tab',value:b.dataset.tab});return;}if(b.dataset.view){dispatch({type:'view',value:b.dataset.view});return;}if(b.dataset.panel&&!b.dataset.action){dispatch({type:'panel',value:b.dataset.panel});return;}if(b.dataset.readerView){state.readerView=b.dataset.readerView;render();return;}if(b.dataset.filter){dispatch({type:'filter',value:b.dataset.filter});return;}if(b.dataset.selectPanel){e.preventDefault();dispatch({type:'panel',value:b.dataset.selectPanel});document.querySelector('#panel-form')?.scrollIntoView({block:'center'});return;}if(b.dataset.editFinding){e.preventDefault();findingModal(Number(b.dataset.editFinding));return;}const a=b.dataset.action,id=b.dataset.id;
if(a==='reset'){state=initial();closeModal();render();return;}
if(a==='new'){newModal();return;}if(a==='modal-close'){closeModal();return;}
if(a==='open'){state.previewDraft=false;dispatch({type:'select',id});return;}
if(a==='back-queue'){dispatch({type:'page',value:'queue'});return;}
if(a==='page-guide'){dispatch({type:'page',value:'guide'});return;}
if(a==='go-body'||a==='go-review'){dispatch({type:'tab',value:a==='go-body'?'body':'review'});window.scrollTo({top:0});return;}
if(a==='finding-new'){findingModal(null,b.dataset.panel);return;}
if(a==='finding-edit'){findingModal(Number(id));return;}
if(a==='finding-remove'){dispatch({type:'finding-remove',id:Number(id)});if(!state.error)closeModal();return;}
if(['cancel-modal','noshow-modal','return-modal','correction-modal','reinspection-modal','withdraw-modal'].includes(a)){reasonModal(a,{'cancel-modal':'Cancel appointment','noshow-modal':'Record no-show','return-modal':'Return to technician','correction-modal':'Create editorial correction','reinspection-modal':'Book a new physical inspection','withdraw-modal':'Withdraw latest report'}[a]);return;}
if(a==='save-draft'){state.message='Draft is retained in this tab’s memory. Reloading clears it; no server save is connected.';state.error=false;render();return;}
if(a==='preview-draft'){state.previewDraft=true;render();return;}if(a==='preview-close'){state.previewDraft=false;render();return;}
if(a==='print-draft'||a==='print-final'){if(a==='print-final'){const o=current(),sn=o.snapshots.find(x=>x.id===id);if(!sn||sn.pdf!=='ready'||!authorized(sn,state.viewer)){state.message='No ready authorized artifact.';state.error=true;render();return;}}document.body.dataset.printKind=a==='print-draft'?'DRAFT · FICTIONAL DEMO':'FICTIONAL DEMO · NOT A REAL INSPECTION';window.print();return;}
if(a==='snapshot-open'){state.selectedSnapshot=id;dispatch({type:'tab',value:'delivery'});return;}
if(a==='archive-open'){state.selectedSnapshot=null;dispatch({type:'select',id,tab:'history'});return;}
if(a==='photo-remove'){dispatch({type:a,target:b.dataset.target,id:b.dataset.target==='finding'?Number(id):id,photo:b.dataset.photo});if(b.dataset.target==='finding'&&!state.error)findingModal(Number(id));return;}
if(a==='guide-start'){startGuide(id);return;}if(a==='guide-next'){advanceGuide();return;}if(a==='guide-prev'){previousGuide();return;}if(a==='guide-restart'){startGuide(state.guide);return;}if(a==='guide-exit'){state.guide=null;render();return;}
if(['pdf-fail','pdf-ready','pdf-retry'].includes(a)){dispatch({type:'pdf',id,value:{'pdf-fail':'failed','pdf-ready':'ready','pdf-retry':'pending'}[a]});return;}
dispatch({type:a,id});});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.summary!==undefined){dispatch({type:'summary',value:t.value},false);return;}if(t.dataset.note){dispatch({type:'answer',id:t.dataset.note,key:'note',value:t.value},false);return;}if(t.dataset.missingCheck){dispatch({type:'answer',id:t.dataset.missingCheck,key:'noEvidence',value:t.value},false);return;}if(t.dataset.template&&t.type!=='checkbox'){dispatch({type:'template-field',id:t.dataset.template,key:t.dataset.key,value:t.value},false);return;}});
document.addEventListener('change',async e=>{const t=e.target;if(t.id==='role'){state.previewDraft=false;dispatch({type:'role',value:t.value});return;}if(t.dataset.answer){dispatch({type:'answer',id:t.dataset.answer,key:'result',value:t.value});return;}if(t.dataset.template&&t.type==='checkbox'){dispatch({type:'template-field',id:t.dataset.template,key:t.dataset.key,value:t.checked},false);return;}if(t.id==='reader-actor'){dispatch({type:'viewer',value:t.value});return;}if(t.id==='snapshot-picker'){state.selectedSnapshot=t.value;render();return;}
if(t.dataset.photoTarget){const f=t.files?.[0];if(!f)return;const target=t.dataset.photoTarget,id=t.dataset.photoId,orderId=state.selected;if(target==='finding'&&document.querySelector('#finding-form')){const form=document.querySelector('#finding-form');const values=Object.fromEntries(new FormData(form));const p=PANELS.find(p=>p[0]===values.panel);dispatch({type:'finding-save',finding:{...values,id:Number(id),view:p[3]}},false);if(state.error){render();return;}}const draftVersion=current()?.report?.version;if(!['image/jpeg','image/png','image/webp'].includes(f.type)||f.size>5_000_000){state.message='Use a JPG, PNG or WebP sample image under 5 MB. Draft notes remain intact.';state.error=true;render();return;}try{const src=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(f);});if(state.selected!==orderId||current()?.report?.version!==draftVersion)return;dispatch({type:'photo',target,id:target==='finding'?Number(id):id,src,caption:'Local sample image · not verified inspection evidence'});if(target==='finding'&&!state.error)findingModal(Number(id));}catch{state.message='Image could not be read. Draft notes are preserved. Choose the image again.';state.error=true;render();}}});
document.addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form);if(form.id==='new-form'){dispatch({type:'create',...Object.fromEntries(f)});if(!state.error)closeModal();return;}if(form.id==='intake-form'){const values=Object.fromEntries(f);for(const key of ['ownerConsent','publicationConsent','matched','planAcknowledged'])values[key]=f.has(key);dispatch({type:'intake',values});return;}if(form.id==='panel-form'){dispatch({type:'panel-status',id:state.panel,status:f.get('status'),reason:f.get('reason')});return;}if(form.id==='finding-form'){const values=Object.fromEntries(f),p=PANELS.find(p=>p[0]===values.panel);dispatch({type:'finding-save',finding:{...values,id:form.dataset.id?Number(form.dataset.id):null,view:p[3]}});if(!state.error)closeModal();return;}if(form.id==='reason-form'){const kind=form.dataset.kind,reason=f.get('reason');const type={'cancel-modal':'cancel','noshow-modal':'no-show','return-modal':'return','correction-modal':'successor','reinspection-modal':'successor','withdraw-modal':'withdraw'}[kind];dispatch({type,reason,mode:kind==='correction-modal'?'correction':'reinspection',date:f.get('date'),mileage:f.get('mileage'),id:current()?.snapshots.at(-1)?.id});if(!state.error)closeModal();return;}});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal();const dialog=$('modal-root').querySelector('[role=dialog]');if(dialog&&e.key==='Tab'){const all=[...dialog.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')];const first=all[0],last=all.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
const initialGuide=new URLSearchParams(location.search).get('guide');if(initialGuide&&GUIDES[initialGuide])startGuide(initialGuide);else render();
